{
  "company": "CRONUS International Ltd.",
  "messageType": "Inventory.Revaluation.PreviewPost",
  "status": "Success",
  "contract": "json",
  "format": "chapters",
  "catalogue": {
    "name": "Inventory.Revaluation.PreviewPost",
    "isEnabled": true,
    "filterTableNo": 233,
    "description": "Forskoðar innbyggða endurmatsbókun og skilar færslum án þess að varðveita þær.",
    "selectionDescription": "Auðkenndu fyrirliggjandi endurmatskeyrslu sem er ekki ítrekunarbók. subject TEMPLATE|BATCH eða SystemId hefur forgang; annars skal nota eitt SystemId auðkenni eða templateName/batchName. SystemId auðkenni hefur forgang yfir nafnaparið.",
    "messageDirection": "Inbound",
    "keywords": [
      "birgðir",
      "endurmat",
      "birgðavirði",
      "reikna",
      "forskoða",
      "bóka"
    ],
    "chargeable": true
  },
  "chapters": {
    "envelope": {
      "subject": {
        "use": "optional",
        "forms": [
          "TEMPLATE|BATCH",
          "systemId"
        ]
      },
      "dataRequired": false,
      "version": "1.0",
      "contentType": "text/json"
    },
    "target": [
      {
        "source": "subject",
        "form": "TEMPLATE|BATCH",
        "description": "The template name and the batch name of the Revaluation journal batch, separated by a vertical bar; each part is at most 10 characters."
      },
      {
        "source": "subject",
        "form": "guid",
        "description": "The SystemId of the Item Journal Batch."
      },
      {
        "source": "data.batchId, data.id, data.systemId, data.recordSystemId",
        "form": "guid",
        "description": "The SystemId of the batch. Used only when subject is empty, and only one of the four keys may be sent."
      },
      {
        "source": "data.templateName, data.batchName",
        "form": "template name and batch name",
        "description": "The Revaluation template and its batch, used when neither subject nor a SystemId key is sent."
      }
    ],
    "parameters": [
      {
        "name": "templateName",
        "type": "string",
        "required": false,
        "description": "Existing Revaluation template, at most 10 characters; supply with batchName if no subject or SystemId alias."
      },
      {
        "name": "batchName",
        "type": "string",
        "required": false,
        "description": "Existing batch, at most 10 characters. Subject or SystemId selection takes precedence."
      },
      {
        "name": "batchId",
        "type": "string",
        "required": false,
        "description": "Batch SystemId; only one SystemId alias may be supplied when subject is absent."
      },
      {
        "name": "id",
        "type": "string",
        "required": false,
        "description": "Alias of batchId."
      },
      {
        "name": "systemId",
        "type": "string",
        "required": false,
        "description": "Alias of batchId."
      },
      {
        "name": "recordSystemId",
        "type": "string",
        "required": false,
        "description": "Alias of batchId."
      }
    ],
    "response": {
      "contentType": "text/json",
      "fields": [
        {
          "name": "status",
          "type": "string",
          "description": "Success."
        },
        {
          "name": "templateName",
          "type": "string",
          "description": "The template of the identified journal batch."
        },
        {
          "name": "batchName",
          "type": "string",
          "description": "The identified journal batch."
        },
        {
          "name": "linesToPost",
          "type": "integer",
          "description": "The number of lines of the batch that the preview included."
        },
        {
          "name": "rollback",
          "type": "boolean",
          "description": "Always true: the previewed entries were rolled back and nothing is kept."
        },
        {
          "name": "preview",
          "type": "array",
          "description": "The entries the posting would create, grouped by table."
        },
        {
          "name": "totals",
          "type": "object",
          "description": "The totals of the previewed G/L entries.",
          "children": [
            {
              "name": "balanced",
              "type": "boolean",
              "description": "True when debit and credit totals agree; present only when the preview has G/L entries."
            },
            {
              "name": "totalDebitLCY",
              "type": "decimal",
              "description": "The total debit amount of the previewed G/L entries."
            },
            {
              "name": "totalCreditLCY",
              "type": "decimal",
              "description": "The total credit amount of the previewed G/L entries."
            }
          ]
        },
        {
          "name": "entryCount",
          "type": "integer",
          "description": "The number of previewed entries in all tables."
        },
        {
          "name": "glEntryCount",
          "type": "integer",
          "description": "The number of previewed G/L entries."
        }
      ]
    },
    "errors": [
      {
        "code": "InvalidParameter",
        "when": "The Costing domain is turned off in Inventory Setup.",
        "fix": "Turn on the Costing domain in Inventory Setup."
      },
      {
        "code": "PermissionDenied",
        "when": "The caller does not hold the Inv. Posting Gate permission set.",
        "fix": "Ask an administrator to assign Inv. Posting Gate."
      },
      {
        "code": "NothingToPreview",
        "when": "The preview would create no entries, so nothing would be posted.",
        "fix": "Check the lines of the Revaluation batch."
      },
      {
        "code": "BusinessCentralError",
        "when": "The batch is not identified, is not a non-recurring batch of a Revaluation journal template, has no lines, has a line without an item or that is not a Revaluation line, a key other than the batch keys is sent, or Business Central refuses the posting in the preview. The text of Business Central is returned as it is, and nothing is kept.",
        "fix": "Correct the batch or its journal lines and preview again."
      }
    ],
    "effect": {
      "effect": "read",
      "writes": false,
      "posts": false,
      "rollback": true,
      "changes": "None. Runs the revaluation posting for the batch, returns the entries it would create, and rolls everything back. Nothing is committed and the journal lines stay unchanged.",
      "idempotent": true,
      "permissionSet": "the Bifrost \"Full Access\" permission set and Inv. Posting Gate",
      "preconditions": [
        "The Costing domain is turned on in Inventory Setup.",
        "The batch is an existing non-recurring batch of a Revaluation journal template with at least one Revaluation line.",
        "The caller holds Inv. Posting Gate and can write item journal lines."
      ]
    },
    "metering": {
      "chargeable": true,
      "chargedAs": "message"
    },
    "related": [
      {
        "name": "Inventory.Revaluation.Post",
        "useInsteadWhen": "Use it to post the batch once the preview is acceptable."
      },
      {
        "name": "Inventory.Revaluation.Calculate",
        "useInsteadWhen": "Use it to read the remaining quantity and value of an item; it does not touch the journal."
      }
    ],
    "workflow": {
      "steps": [
        {
          "messageType": "Inventory.Revaluation.Calculate",
          "purpose": "Read the remaining quantity and value of an item to decide the new value."
        },
        {
          "messageType": "Inventory.Revaluation.PreviewPost",
          "purpose": "Preview the entries the Revaluation batch would create."
        },
        {
          "messageType": "Inventory.Revaluation.Post",
          "purpose": "Post the batch once the preview is acceptable."
        }
      ]
    },
    "examples": [
      {
        "title": "Preview the Revaluation batch DEFAULT of template REVAL",
        "request": {
          "type": "Inventory.Revaluation.PreviewPost",
          "data": {
            "templateName": "REVAL",
            "batchName": "DEFAULT"
          }
        },
        "response": {
          "status": "Success",
          "templateName": "REVAL",
          "batchName": "DEFAULT",
          "linesToPost": 2,
          "rollback": true,
          "preview": [],
          "totals": {
            "balanced": true,
            "totalDebitLCY": 120.5,
            "totalCreditLCY": 120.5
          },
          "entryCount": 6,
          "glEntryCount": 4
        }
      }
    ],
    "overview": "Runs native revaluation posting preview and returns captured entries without committing. Identify an existing nonrecurring Revaluation batch. Subject TEMPLATE|BATCH or SystemId takes precedence; otherwise use one SystemId alias or templateName/batchName. A SystemId alias precedes the name pair.",
    "notes": "The batch is posted and rolled back, so nothing is committed and the journal lines stay unchanged; the answer carries rollback true, the entries grouped by table in preview, totals and the entry counts. The batch is identified as in Inventory.Revaluation.Post and must have Revaluation lines that have an item number. A preview that would create no entries is answered with NothingToPreview, and a refusal from Business Central is returned as BusinessCentralError with its own text. The call can be repeated freely. The caller needs the Bifrost \"Full Access\" permission set and Inv. Posting Gate, as for posting, and the Costing domain must be on in Inventory Setup."
  },
  "conventions": "## Errors and warnings\r\nAn error response has `status` = `Error`, a stable `code`, the `error` text and, when they apply, `parameter` (the request parameter concerned, e.g. `lines[2].no`), `received` (the value received), `expected` (what was expected) and `nextStep` (what to do now). `hint` says where to read more.\r\nWhen a request has several problems, all of them are listed in `errors[]` - each with the same fields - under a top-level `code` (`MultipleErrors`, or a shared code such as `InvalidLine` for the `lines` of a Create type) and a summary `error`. Fix them all before calling again. One problem is reported at the top level, with no `errors[]`.\r\nRequest values are checked first and every problem found is reported together. A Business Central validation error raised afterwards, while a record is being written, stops the call and is reported on its own: `code` = `BusinessCentralError`, Business Central's own `error` text, and `parameter` naming the request parameter being applied, e.g. `lines[1].accountNo`. Nothing is written.\r\nRequest values are read in one format, whatever the language: dates `YYYY-MM-DD`; date-times ISO 8601 with `Z` or an offset; amounts as JSON numbers (or a string such as `\"1234.56\"`, no thousands separator); integers as JSON integers; booleans `true` or `false`. Any other value is `InvalidParameterFormat` with `received` and `expected`; for an unambiguous local form such as `26.09.2026`, `nextStep` gives the value to resend. Every bad value of a request is reported together.\r\nAnswers are written in one format as well, whatever the language of the call: dates `YYYY-MM-DD`, date-times ISO 8601, numbers with a dot and no thousands separator, and the option and enum values of every answer except `Data.Records.Get` and `Data.Records.Set` as their English names, so a value read from an answer can be sent back. Those two answer the caption of the language of the call, for a person to read. The language of the call (`lcid`) changes captions and message texts, not these forms. Two things are outside Bifrost's control: Business Central writes its own texts (a ledger entry description such as `Direct Cost V00010 on 10/02/26`, the text of a `BusinessCentralError`) with the regional settings of the server session, which `lcid` does not change, so a date in such a text can be in month-day order; and a table view is read with those settings too, so write dates in a view as `YYYY-MM-DD` and decimals with a dot.\r\nBoth success and error responses can carry `warnings[]`, each with `code`, `message` and, when they apply, `parameter` and `nextStep`.\r\n`UnknownParameter` refuses undeclared data keys before execution for every type whose effect is not read, including a missing effect. The root envelope option `strict:false` cannot opt out. Read types keep warnings without changing status, validationResult or domain warningCount unless the caller sets `strict:true` (next to type and subject, never inside data). Refusals list the keys and localized nextStep corrections; no business changes or successful execution charges occur. Example: {\"type\":\"Memory.User.Set\",\"strict\":true,\"data\":{\"memory\":\"test\",\"memry\":\"typo\"}} is refused.\r\n`FieldChangedByBC` is a warning from Data.Records.Set: another field validation or the write changed a sent field after its own validation. `parameter` names data[n].fields.{jsonName}, counting from 0. Status stays Success. Compare the returned values with what you sent; follow `nextStep` to use validation order or send the field again in a separate call. Normalisation of the field itself, LCY, Dimension Set ID, BLOB, Media, MediaSet and skipped fields are excluded.\r\nViðbætur (Foundation 28.0.8 eða nýrri) geta kallað á `Argument.SetErrorContext(Parameter, Expected, NextStep)` fyrir aðgerð sem gæti mistekist eftir gagnaskrif og síðan `Argument.ClearErrorContext()` eftir að hún tekst. Gefðu upp heiti færibreytu og þýddan texta, aldrei gildi úr beiðni, skráarinnihald, aðgangsupplýsingar eða kallstafla. Foundation skilar þessu samhengi með upprunalegu `BusinessCentralError` eftir afturköllun, einnig við ómeðhöndlaðar verkefnisvillur; `RespondWithLastError()` notar það líka. Viðmótið grípur ekki villur, staðfestir ekki gagnaskrif og breytir ekki færslumörkum. Haltu `Codeunit.Run` án skilagildis og láttu villur berast áfram þegar `OmitCommit` köll eru keðjuð; bættu aldrei við Boolean `Codeunit.Run` eða `TryFunction` sem skrifar gögn til að endurheimta samhengi. Samhengið er hreinsað milli skilaboða. Kallendur án samhengis halda óbreyttri uppbyggingu svars; þekktar læsingarvillur halda núverandi `Retryable` leiðbeiningum.\r\nSkilaboðagerð sem má aðeins keyra eftir einni leið (Foundation 28.0.9 eða nýrri) les `Argument.GetInvocationSource()`: `Queue` þegar verkraðari keyrir skilaboð sem biðraðarviðmótið setti í röð, `Task` fyrir verkviðmótið (`/tasks`), `Dispatcher` fyrir innra kall í gegnum `Dispatcher ori` (innbyggða MCP-verkfæraþjóninn, hreiðrað kall úr annarri skilaboðagerð) og `Direct` fyrir aðgerðina Keyra vinnslu á síðunni Skilaboð og allt sem ekki er skráð. Aðeins Foundation skráir gildið; gildi í beiðni, færibreytur, uppruni, efni og skrif í færibreytuna breyta því ekki. Hafnaðu öðrum leiðum með `PreconditionFailed` og `nextStep` sem nefnir leiðina sem á að nota.\r\n`Retryable` means a transient lock or deadlock caught while writing or posting. `error` keeps Business Central's original text. `expected` is \"no concurrent lock on the same records\"; `nextStep` is \"Retry the same call after a few seconds; nothing was changed.\" Bifrost does not retry automatically. Other platform errors, including uncaught queue-path errors, remain `BusinessCentralError`.\r\nCodes: `MissingParameter`, `InvalidParameterFormat`, `InvalidParameter`, `RecordNotFound`, `AmbiguousRecord`, `ConflictingIdentifiers`, `InvalidFilterField`, `InvalidLine`, `NothingToPreview`, `LinesSkipped`, `BlockedByWriteGuard`, `PreconditionFailed`, `PermissionDenied`, `LimitExceeded`, `BusinessCentralError`, `MultipleErrors`, `DeprecatedParameter`, `UnknownParameter`, `FieldChangedByBC`, `Retryable`, `EULA_REQUIRED`, `TRIAL_NOT_STARTED`. The `error` text may be translated; the code never is.\r\n"
}
